import 'package:dashboard/features/comic/manhuatai/manhuatai_book.dart';
import 'package:dashboard/features/comic/manhuatai/manhuatai_json.dart';

/// Payload of a book-list response: `data.name` plus the section list.
///
/// Source: `lib/models/book_list.dart` → `Data` (a `Data` class regenerated by
/// hand here under a domain-specific name to keep one class per file).
class ManhuataiBookSection {
  const ManhuataiBookSection({required this.book, required this.name});

  final List<ManhuataiBook> book;
  final String name;

  static const ManhuataiBookSection empty =
      ManhuataiBookSection(book: <ManhuataiBook>[], name: '');

  bool get isEmpty => book.isEmpty;

  factory ManhuataiBookSection.fromJson(Map<String, dynamic> json) {
    final source = ManhuataiJson.map(json);
    return ManhuataiBookSection(
      book: ManhuataiJson.maps(source['book']).map(ManhuataiBook.fromJson).toList(),
      name: ManhuataiJson.asString(source['name']),
    );
  }

  Map<String, dynamic> toJson() => <String, dynamic>{
        'book': book.map((item) => item.toJson()).toList(),
        'name': name,
      };
}
